      { label: 'expense.edit_requests.col_new', value: this.fmtMoney(item.requested_amount) },
      { label: 'common.date', value: item.requested_at ? (this.dateTime.transform(item.requested_at) ?? '—') : '—' },
      { label: 'expense.list.col_review', value: item.reviewed_by ?? '—' },
    ];
  }

  /**
