  comparison(item: EditRequestDetail): ComparisonRow[] {
    const orig = item.original_data ?? {};
    const req = item.requested_changes ?? {};
    const rows: ComparisonRow[] = [];
    if ('amount' in req) {
      rows.push({ label: 'common.amount', before: this.fmtMoney(orig.amount), after: this.fmtMoney(req.amount) });
    }
    if ('description' in req) {
      rows.push({ label: 'expense.detail.description', before: this.fmtText(orig.description), after: this.fmtText(req.description) });
    }
    if ('location' in req) {
      rows.push({ label: 'expense.form.location', before: this.fmtText(orig.location), after: this.fmtText(req.location) });
    }
    if ('expense_category_id' in req) {
      rows.push({
        label: 'expense.detail.direction',
        before: this.fmtText(orig.expense_category_path ?? orig.expense_category_name ?? orig.expense_category_id),
        after: this.fmtId(req.expense_category_id),
      });
    }
    if ('expense_item_id' in req) {
      rows.push({
        label: 'direction.picker.item',
        before: this.fmtText(orig.expense_item_name ?? orig.expense_item_id),
        after: this.fmtId(req.expense_item_id),
      });
    }
    if ('social_case_id' in req) {
      rows.push({
        label: 'expense.detail.case',
        before: this.fmtText(orig.social_case_name ?? orig.social_case_id),
        after: this.fmtId(req.social_case_id),
      });
    }
    if ('attachment' in req) {
      rows.push({
        label: 'expense.detail.attachment',
        before: this.fmtText(orig.attachment ? basename(orig.attachment as string) : null),
        after: req.attachment === null
          ? this.translate.instant('expense.edit_requests.detail.attachment_removed')
          : this.fmtText(req.attachment ? basename(req.attachment as string) : null),
      });
    }
    if ('expense_date' in req) {
      rows.push({ label: 'common.date', before: this.fmtDate(orig.expense_date), after: this.fmtDate(req.expense_date) });
    }
    if ('type' in req) {
      rows.push({ label: 'common.type', before: this.enumLabel(orig.type), after: this.enumLabel(req.type) });
    }
    if ('line_items' in req) {
      rows.push({
        label: 'expense.detail.line_items',
        before: this.fmtLineItems(orig.line_items),
        after: this.fmtLineItems(req.line_items),
      });
    }
    return rows;
  }

  approve(): void {
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(this.http.post<ActionResponse>(`/expenses/edit-requests/${this.id()}/approve`, {}))
      .then((res) => {
        this.sending.set(false);
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.actionError.set((err as HttpErrorResponse));
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code);
      });
  }

  reject(reason: string): void {
    this.sending.set(true);
    this.actionError.set(null);
    void firstValueFrom(
      this.http.post<ActionResponse>(`/expenses/edit-requests/${this.id()}/reject`, { rejection_reason: reason }),
    )
      .then((res) => {
        this.sending.set(false);
        this.rejectDialogRef()?.done();
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.actionError.set((err as HttpErrorResponse));
      });
  }

  private fmtMoney(value: unknown): string {
    if (value === null || value === undefined || value === '') {
      return '—';
    }
    if (typeof value === 'string' || typeof value === 'number') {
      return this.money.transform(value, false);
    }
    return '—';
  }

  private fmtText(value: unknown): string {
    if (value === null || value === undefined || value === '') {
      return '—';
    }
    if (typeof value === 'string' || typeof value === 'number') {
      return String(value);
    }
    return '—';
  }

  private fmtId(value: unknown): string {
    if (typeof value === 'string' || typeof value === 'number') {
      return `#${String(value)}`;
    }
    return '—';
  }

  private fmtDate(value: unknown): string {
    if (typeof value !== 'string' || value === '') {
      return '—';
    }
    return this.dateTime.transform(value, false) ?? '—';
  }

  private enumLabel(value: unknown): string {
    if (typeof value !== 'string' || value === '') {
      return '—';
    }
    const key = `enums.expense_type.${value}`;
    const label = this.translate.instant(key);
    return label !== key ? label : value;
  }

  /** sanitized rows [{description, quantity, unit_price}] or legacy {raw_text} */
  private fmtLineItems(value: unknown): string {
    if (Array.isArray(value)) {
      const parts = value.map((item) => {
        if (item !== null && typeof item === 'object' && 'description' in item) {
          const row = item as { description?: unknown; quantity?: unknown };
          const description = typeof row.description === 'string' || typeof row.description === 'number' ? String(row.description) : '';
          const quantity = typeof row.quantity === 'string' || typeof row.quantity === 'number' ? ` ×${row.quantity}` : '';
          return `${description}${quantity}`;
        }
        return String(item);
      });
      return parts.length > 0 ? parts.join('، ') : '—';
    }
    if (value !== null && typeof value === 'object' && 'raw_text' in value) {
      const raw = (value as { raw_text?: unknown }).raw_text;
      return typeof raw === 'string' && raw !== '' ? raw : '—';
    }
    return '—';
  }
}

/** "expense_attachments/abc.pdf" → "abc.pdf" (display only) */
function basename(path: string): string {
  const parts = path.split('/');
  return parts[parts.length - 1] || path;
}

