      .then((res) => {
        this.markingAll.set(false);
        this.toast.success(res.message);
        this.data.reload();
        this.polling.refreshNow();
      })
      .catch((err: unknown) => {
        this.markingAll.set(false);
        this.toast.apiError(this.errMsg(err));
      });
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
