  type: string | null;
}

/** The API show payload mapped onto the form field names. */
interface CasePayload {
  id: number;
  name: string | null;
  phone: string | null;
  national_id: string | null;
  nationality: string | null;
  address: string | null;
  governorate: string | null;
  district: string | null;
  housing_type: string | null;
