        [path]="'/treasury/' + id() + '/delete'"
        [entity]="safeValue()?.name ?? ''"
        (deleted)="onDeleted()"
      />
    } @else if (data.isLoading()) {
      <div class="skeleton skeleton--title u-mb-4"></div>
      <div class="skeleton skeleton--tile"></div>
    } @else {
