/**
 * Attachment field (plan 11.9, T24): current file with open/replace/remove,
 * type and size validation. Removal in edit requests applies only on approval.
 */
@Component({
  selector: 'app-attachment-field',
  standalone: true,
  imports: [TranslatePipe, ButtonModule, FileUploadModule, FormsModule],
  template: `
    <div class="u-column u-gap-2 u-full">
      @if (current() && !removed()) {
        <div class="attachments__file">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-paperclip" />
          </svg>
          <span class="attachments__name u-bidi">{{ current() }}</span>
          @if (downloadUrl()) {
            <a [href]="downloadUrl()" target="_blank" rel="noopener">
              {{ 'common.open' | translate }}
            </a>
          }
          @if (canRemove()) {
            <p-button [label]="'common.remove' | translate" size="small" [text]="true" severity="danger" (onClick)="remove.emit()" />
          }
        </div>
      }

      @if (!removed()) {
        <p-fileupload
          mode="basic"
          [customUpload]="true"
          (onSelect)="onSelect($event)"
          [chooseLabel]="current() ? ('common.replace' | translate) : ('common.choose_file' | translate)"
          [auto]="true"
          [maxFileSize]="maxSize()"
        />
        @if (error()) {
          <p class="field__error">{{ error() | translate }}</p>
        }
      }
      @else {
        <p class="field__hint">{{ 'expense.form.attachment_removed' | translate }}</p>
        <p-button [label]="'common.undo' | translate" size="small" [text]="true" (onClick)="removed.set(false)" />
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AttachmentFieldComponent {
  current = input<string | null>(null);
  downloadUrl = input<string | null>(null);
  canRemove = input(true);
  maxSize = input(5_000_000);

  removed = signal(false);
  error = signal('');

  fileChange = output<File | null>();
  remove = output();

  onSelect(event: { files: File[] }): void {
    const file = event.files?.[0];
    if (!file) {
      return;
    }
    if (!['image/jpeg', 'image/png', 'image/webp', 'application/pdf'].includes(file.type)) {
      this.error.set('validation.file_type');
      return;
    }
    this.error.set('');
    this.removed.set(false);
    this.fileChange.emit(file);
  }
}

import type {
  ElementRef,
  OnDestroy} from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { ButtonModule } from 'primeng/button';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { MotionService } from '@core/motion/motion.service';

export interface ChartSeries {
  label: string;
  value: number;
}

/**
 * Titled chart card (plan 16.2). Chart.js loads lazily on the routes that
 * use it. The chart reacts to series() changes — when async data arrives,
 * the chart is created or updated. "View as table" is the a11y version.
 */
@Component({
  selector: 'app-chart-card',
  standalone: true,
  imports: [TranslatePipe, ButtonModule, MoneyPipe],
  template: `
    <div class="chart-card">
      <div class="chart-card__head">
        <span class="chart-card__title">{{ title() | translate }}</span>
        <span class="chart-card__spacer"></span>
        <!-- stopPropagation: the card may sit inside a routerLink wrapper —
             the toggle must switch views in place, never navigate -->
        <p-button
          [label]="(asTable() ? 'common.view_chart' : 'common.view_table') | translate"
          [text]="true"
          size="small"
          (onClick)="toggleView($event)"
        />
      </div>

      <div class="chart-card__body">
        @if (series().length === 0) {
          <p class="u-muted">{{ 'common.no_data' | translate }}</p>
        } @else if (asTable()) {
          <table class="chart-card__table">
            <thead>
              <tr>
                <th scope="col">{{ 'common.name' | translate }}</th>
                <th scope="col">{{ 'common.value' | translate }}</th>
                <th scope="col">%</th>
              </tr>
            </thead>
            <tbody>
              @for (row of tableRows(); track row.label) {
                <tr>
                  <td>{{ row.label }}</td>
                  <td class="u-bidi">{{ row.value | money: false }}</td>
                  <td class="u-bidi">{{ row.percent }}</td>
                </tr>
              }
            </tbody>
          </table>
        } @else {
          <div #host class="u-full" [style.height.px]="height()" style="position: relative;"></div>
        }
      </div>
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChartCardComponent implements OnDestroy {
  title = input.required<string>();
  series = input.required<ChartSeries[]>();
  height = input(220);
  chartType = input<'doughnut' | 'bar'>('doughnut');

  private motion = inject(MotionService);
  private host = viewChild<ElementRef<HTMLDivElement>>('host');
  readonly asTable = signal(false);

  // fixed series order: brand, light, ink, taupe, mid, sand (plan 10.1.4)
  private readonly palette = ['#5D3722', '#9E877A', '#4F2F1D', '#BEAFA7', '#7D5F4E', '#DFD7D3'];
  private chart: { destroy: () => void; data: { labels: string[]; datasets: { data: number[] }[] } } | null = null;
  private chartLib: (new (
    el: HTMLCanvasElement,
    cfg: Record<string, unknown>,
  ) => { destroy: () => void }) | null = null;

  toggleView(event: Event): void {
    event.stopPropagation();
    event.preventDefault();
    this.asTable.set(!this.asTable());
  }

  tableRows = computed(() => {
    const total = this.series().reduce((sum, s) => sum + s.value, 0);
    return this.series().map((s) => ({
      label: s.label,
      value: s.value,
      percent: total > 0 ? Math.round((s.value / total) * 100) : 0,
    }));
  });

  constructor() {
    // React to series changes: create or update chart when data arrives
    effect(async () => {
      const series = this.series();
      const showTable = this.asTable();

      if (series.length === 0 || showTable) {
        this.destroyChart();
        return;
      }

      // Wait a tick for the #host div to render (it's inside @else)
      await new Promise((r) => setTimeout(r, 0));

      const el = this.host()?.nativeElement;
      if (!el) return;

      await this.renderChart(el, series);
    });
  }

  private async renderChart(el: HTMLDivElement, series: ChartSeries[]): Promise<void> {
    // Load Chart.js once — use /auto which registers all scales and controllers
    if (!this.chartLib) {
      const mod = (await import('chart.js/auto')) as unknown as {
        Chart: new (
          el: HTMLCanvasElement,
          cfg: Record<string, unknown>,
        ) => { destroy: () => void };
      };
      this.chartLib = mod.Chart;
    }

    // Destroy old chart
    this.destroyChart();

    // Clear host and create canvas
    el.innerHTML = '';
    const canvas = document.createElement('canvas');
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    el.appendChild(canvas);

    const labels = series.map((s) => s.label);
    const values = series.map((s) => s.value);
    const colors = series.map((_, i) => this.palette[i % this.palette.length]);
    const surfaceColor =
      getComputedStyle(document.documentElement).getPropertyValue('--color-surface').trim() || '#fff';

    this.chart = new this.chartLib(canvas, {
      type: this.chartType(),
      data: {
        labels,
        datasets: [
          {
            data: values,
            backgroundColor: colors,
            borderColor: surfaceColor,
            borderWidth: 2,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: this.motion.level() === 'full' ? { duration: 350 } : false,
        plugins: {
          legend: {
            display: series.length <= 6,
            position: 'bottom',
            labels: { boxWidth: 10, font: { size: 11 }, color: surfaceColor },
          },
        },
        ...(this.chartType() === 'bar' ? { scales: { y: { beginAtZero: true } } } : {}),
      },
    }) as typeof this.chart;
  }

  private destroyChart(): void {
    if (this.chart) {
      this.chart.destroy();
      this.chart = null;
    }
  }

  ngOnDestroy(): void {
    this.destroyChart();
  }
}

