    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DataTableComponent {
  private storage = inject(LocalStorageService);
  private translate = inject(TranslateService);
  private route = inject(ActivatedRoute);
  readonly body = contentChild(TableBodyDirective);

  /** per-component key; the storage key is prefixed with the page route */
  tableKey = input('');
  columns = input.required<TableColumn[]>();
  rows = input.required<unknown[]>();
  total = input(0);
  perPage = input(25);
  first = input(0);
  loading = input(false);
  title = input('');
  summary = input<Record<string, string>>({});

  pageChange = output<TablePageEvent>();

  searchQuery = signal('');
  state = signal<TableState>({});
  density = signal<'comfortable' | 'compact'>(this.storage.get('table.density', 'comfortable'));

  /** page route path (e.g. "users", "custodies/mine") — scopes saved state per page */
  private readonly routePath = this.route.pathFromRoot
    .map((r) => r.routeConfig?.path)
    .filter((p): p is string => !!p && !p.includes(':'))
    .join('/');

  private readonly storageKey = computed(() => {
    const key = this.tableKey() || this.title() || 'table';
    return this.routePath ? `${this.routePath}/${key}` : key;
  });

  private readSavedState(): TableState {
    return this.storage.get<TableState>(`table.state.${this.storageKey()}`, {});
  }

  /**
   * Saved sort restored ONCE — p-table's [sortField]/[sortOrder] inputs are
   * constant after init. Re-binding them on every save made PrimeNG toggle
   * its internal order twice (input feedback), so descending never fired.
   */
  readonly initialState = this.readSavedState();

  constructor() {
    effect(() => {
      const key = this.storageKey();
      const saved = this.storage.get<TableState>(`table.state.${key}`, {});
      this.state.set(saved);

      // seed the first data fetch with the saved sort so header and rows agree
      const savedSortField = typeof saved.sortField === 'string' ? saved.sortField : '';
      if (savedSortField !== '') {
        this.pageChange.emit({
          page: 1,
          per_page: saved.rows ?? 25,
          sort: (saved.sortDir === -1 ? '-' : '') + String(savedSortField),
        });
      }
    });
  }

  /**
   * Places a body cell at its column's position (used by TableColDirective).
   * Each cell places ITSELF when created and whenever the saved column order
   * changes — no bulk DOM permutation that could race with PrimeNG's row
   * re-rendering (pagination/sort/filter recreate rows in template order).
   */
  placeCell(td: HTMLTableCellElement, field: string): void {
    const ordered = this.orderedColumns();
    const targetIdx = ordered.findIndex((c) => c.field === field);
    if (targetIdx < 0) return;
    const tr = td.parentElement;
    if (!tr) return;

    const cells = [...tr.children].filter((c) => c.tagName === 'TD');
    const currentIdx = cells.indexOf(td);
    if (currentIdx === -1 || currentIdx === targetIdx) return;

    // moving down needs the slot AFTER the target; moving up lands on it
    const ref = currentIdx < targetIdx ? cells[targetIdx + 1] : cells[targetIdx];
    tr.insertBefore(td, ref);
  }

  /** rows filtered client-side — matches what the user SEES: raw values,
   *  comma-formatted money, dd/mm/yyyy dates, and translated enum labels */
  filteredRows = computed(() => {
    const q = this.searchQuery().trim().toLowerCase();
    const rows = this.rows();
    if (!q || !Array.isArray(rows)) return rows;
    const qPlain = q.replace(/,/g, '');
    const fields = this.orderedColumns().map((c) => c.searchField ?? c.field);
    return rows.filter((row) =>
      fields.some((field) => this.cellMatches(this.fieldValue(row, field), q, qPlain)),
    );
  });

  /** one cell's value in every form the interface might display it */
  private cellMatches(value: unknown, q: string, qPlain: string): boolean {
    // objects can never match a text query (and previously stringified to
    // "[object Object]", which matched nothing either)
    if (value === null || value === undefined || typeof value === 'object') return false;
    const raw = String(value as string | number | bigint | boolean | symbol);
    if (raw.toLowerCase().includes(q)) return true;

    // money: stored "5000.00", displayed "5,000.00"
    if (qPlain && /^-?[\d.]+$/.test(raw) && raw.includes(qPlain)) return true;

    // dates: stored ISO "2026-10-27T…", displayed "27/10/2026"
    const d = /^(\d{4})-(\d{2})-(\d{2})/.exec(raw);
    if (d && `${d[3]}/${d[2]}/${d[1]}`.includes(q)) return true;

    // enums: stored code ("closed"), displayed label ("مغلقة")
    return this.enumLabels(raw).some((label) => label.toLowerCase().includes(q));
  }

  /** every translated label for a value across enum namespaces (cached) */
  private readonly labelCache = new Map<string, string[]>();
  private enumLabels(value: string): string[] {
    const cached = this.labelCache.get(value);
    if (cached) return cached;
    const labels: string[] = [];
    for (const ns of ENUM_NAMESPACES) {
      const key = `enums.${ns}.${value}`;
      const label = this.translate.instant(key);
      if (label && label !== key) labels.push(label);
    }
    this.labelCache.set(value, labels);
    return labels;
  }

  /** dot-path lookup: "agent.name" → row.agent?.name; any value type allowed */
  private fieldValue(row: unknown, field: string): unknown {
    return field.split('.').reduce<unknown>((acc, part) => {
      if (acc !== null && acc !== undefined && typeof acc === 'object') {
        return (acc as Record<string, unknown>)[part];
      }
      return undefined;
    }, row);
  }

  /** Columns reordered + widths restored from saved state */
  orderedColumns = computed(() => {
    const input = this.columns();
    if (!Array.isArray(input) || input.length === 0) return [];
    const cols = [...input];
    const order = this.state().columnOrder;
    if (!order || order.length === 0) return cols;

    const fieldSet = new Set(cols.map((c) => c.field));
    const ordered: TableColumn[] = [];
    for (const field of order) {
      const col = cols.find((c) => c.field === field);
      if (col && fieldSet.has(field)) {
        ordered.push(col);
        fieldSet.delete(field);
      }
    }
    // append any new columns not in the saved order
    for (const col of cols) {
      if (fieldSet.has(col.field)) {
        ordered.push(col);
      }
    }
    return ordered;
  });

  /** aria-sort for the focused column header */
  ariaSort(field: string): 'ascending' | 'descending' | 'none' {
    if (this.state().sortField !== field) return 'none';
    return this.state().sortDir === -1 ? 'descending' : 'ascending';
  }

  columnWidth(field: string): string | null {
    return this.state().columnWidths?.[field] ?? null;
  }

  /** restored table width (expand resize mode grows the table past 100%) */
  tableStyle(): { width: string } | undefined {
    const w = this.state().tableWidth;
    return w ? { width: w } : undefined;
  }

  summaryEntries(): { label: string; value: string }[] {
    return Object.entries(this.summary()).map(([label, value]) => ({ label, value }));
  }

  onSearch(term: string): void {
    // purely client-side: filteredRows recomputes, no server reload
    this.searchQuery.set(term);
  }

  toggleDensity(): void {
    const next = this.density() === 'comfortable' ? 'compact' : 'comfortable';
    this.density.set(next);
    this.storage.set('table.density', next);
  }

  resetState(): void {
    this.storage.remove(`table.state.${this.storageKey()}`);
    this.state.set({});
    this.searchQuery.set('');
  }

  onColReorder(event: { dragIndex?: number | null; dropIndex?: number | null }): void {
    const cols = [...this.orderedColumns()];
    const dragIdx = event.dragIndex ?? 0;
    const dropIdx = event.dropIndex ?? 0;
    const moved = cols.splice(dragIdx, 1)[0];
    cols.splice(dropIdx, 0, moved);
    this.saveState({ columnOrder: cols.map((c) => c.field) });
  }

  onColResize(event: { element?: HTMLElement | null; delta?: number | null }): void {
    const element = event.element ?? null;
    const field = element?.getAttribute('data-field');
    if (!element || !field) return;
    const offsetWidth = element.offsetWidth > 0 ? element.offsetWidth : 100;
    const width = element.style.width !== '' ? element.style.width : `${offsetWidth}px`;
    // PrimeNG (expand mode) also grew the table element — persist that too,
    // otherwise restored column widths can exceed the 100% container
    const table = element.closest('table');
    const tableWidth = table !== null && table.style.width !== '' ? table.style.width : undefined;
    const widths = { ...(this.state().columnWidths ?? {}), [field]: width };
    this.saveState({ columnWidths: widths, ...(tableWidth ? { tableWidth } : {}) });
  }

  onLazyLoad(event: {
    first?: number | null;
    rows?: number | null;
    sortField?: string | string[] | null;
    sortOrder?: number | null;
  }): void {
    const first = event.first ?? 0;
    const rows = event.rows ?? 25;
    const sortField = Array.isArray(event.sortField) ? event.sortField[0] : event.sortField;
    let sort = '';
    if (sortField) {
      sort = (event.sortOrder === -1 ? '-' : '') + sortField;
    }

    // persist sort + page size
    this.saveState({
      sortField: sortField ?? '',
      sortDir: event.sortOrder ?? 0,
      rows,
    });

    this.pageChange.emit({
      page: Math.floor(first / Math.max(rows, 1)) + 1,
      per_page: rows,
      sort,
    });
  }

  private saveState(partial: Partial<TableState>): void {
    const current = this.state();
    const next = { ...current, ...partial };
    this.state.set(next);
    this.storage.set(`table.state.${this.storageKey()}`, next);
  }
}

/** enum namespaces used across the app — for search label matching */
const ENUM_NAMESPACES = [
  'custody_status', 'transfer_status', 'return_request', 'review_state', 'social_case',
  'purchase_request', 'maintenance_request', 'task', 'salary', 'edit_request',
  'broadcast', 'transaction_type', 'expense_type', 'priority',
] as const;

import { ChangeDetectionStrategy, Component, computed, input, model, output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import type { HttpErrorResponse } from '@angular/common/http';
import type { ApiErrorBody } from '../../models/api.models';

/**
 * One pattern for every modal form (plan 11.14): inline field errors stay in
 * the page form; this host shows the general alert, keeps values on error,
 * and disables submit while sending (T25).
 */
@Component({
  selector: 'app-form-dialog',
  standalone: true,
  imports: [TranslatePipe, DialogModule, ButtonModule, FormsModule],
  template: `
    <p-dialog appendTo="body"
      [visible]="visible()"
      (visibleChange)="visible.set($event)"
      [header]="header() | translate"
      [modal]="true"
      [draggable]="false"
      [resizable]="false"
      styleClass="dialog"
      [breakpoints]="{ '576px': '100vw' }"
      [style]="{ width: 'min(560px, 94vw)' }"
      [closable]="!sending()"
    >
      <ng-content />
      @if (alert()) {
        <div class="dialog__alert" role="alert">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          <span>{{ alert() }}</span>
        </div>
      }
      <p-footer>
        <div class="u-flex u-gap-2" style="justify-content: flex-end">
          <p-button
            [label]="'common.cancel' | translate"
            severity="secondary"
            [text]="true"
            (onClick)="cancel()"
            [disabled]="sending()"
          />
          <p-button
            [label]="submitLabel() | translate"
            (onClick)="submit.emit()"
            [loading]="sending()"
            [disabled]="sending()"
          />
        </div>
      </p-footer>
    </p-dialog>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FormDialogComponent {
  header = input.required<string>();
  submitLabel = input('common.save');
  sending = input(false);
  error = input<HttpErrorResponse | null>(null);

  visible = model(false);
  submit = output();
  closed = output();

  alert = computed(() => {
    const err = this.error();
    if (!err) {
      return null;
    }
    const body = err.error as ApiErrorBody | null;
    return body?.message ?? null;
  });

  open(): void {
    this.visible.set(true);
  }

  close(): void {
    this.visible.set(false);
    this.closed.emit();
  }

  cancel(): void {
    this.close();
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { DecimalPipe } from '@angular/common';
import { TranslatePipe } from '@ngx-translate/core';
import { ButtonModule } from 'primeng/button';
import { InputNumberModule } from 'primeng/inputnumber';
import { InputTextModule } from 'primeng/inputtext';
import { IconComponent } from '@shared/ui/icon/icon.component';

export interface LineItem {
  description: string;
  quantity: number;
  unit_price: number;
}

/**
 * Line items editor (plan 11.10, T4/T5/D3): rows with a running total and a
 * NON-BLOCKING warning when the total differs from the expense amount.
 */
@Component({
  selector: 'app-line-items-editor',
  standalone: true,
  imports: [DecimalPipe, TranslatePipe, FormsModule, ButtonModule, InputTextModule, InputNumberModule, IconComponent],
  template: `
    <div class="u-column u-gap-2 u-full">
      @for (item of items(); track $index; let i = $index) {
        <div class="line-items__row">
          <input
            pInputText
            type="text"
            [(ngModel)]="item.description" [name]="'li-desc-' + i"
            (ngModelChange)="change()"
            [placeholder]="'expense.form.line_items.description' | translate"
            [attr.aria-label]="'expense.form.line_items.description' | translate"
          />
          <p-inputnumber
            [(ngModel)]="item.quantity" [name]="'li-qty-' + i"
            (ngModelChange)="change()"
            [min]="1"
            [showButtons]="true"
            [attr.aria-label]="'expense.form.line_items.quantity' | translate"
            size="small"
          />
          <div class="line-items__cell-price">
            <p-inputnumber
              [(ngModel)]="item.unit_price" [name]="'li-price-' + i"
              (ngModelChange)="change()"
              [minFractionDigits]="2"
              [maxFractionDigits]="2"
              [min]="0"
              mode="decimal"
              [attr.aria-label]="'expense.form.line_items.unit_price' | translate"
              size="small"
            />
          </div>
          <p-button severity="danger" [text]="true" (onClick)="removeRow(i)" [ariaLabel]="'common.remove' | translate">
            <ng-template pTemplate="icon"><app-icon name="trash" [size]="14" /></ng-template>
          </p-button>
        </div>
      }
      <div>
        <p-button [label]="'expense.form.line_items.add' | translate" size="small" [outlined]="true" (onClick)="addRow()" />
      </div>
      <div class="line-items__total">
        <span>{{ 'expense.form.line_items.total' | translate }}:</span>
        <strong class="u-bidi">{{ total() | number: '1.2-2' }}</strong>
        {{ 'common.egp' | translate }}
      </div>
      @if (mismatch()) {
        <div class="line-items__warning" role="status">
          <svg width="14" height="14" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          {{ 'expense.form.line_items.mismatch' | translate }}
        </div>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LineItemsEditorComponent {
  amount = input<number>(0);

  items = signal<LineItem[]>([{ description: '', quantity: 1, unit_price: 0 }]);
  itemsChange = output<LineItem[]>();

  total = computed(() =>
    this.items().reduce((sum, item) => sum + (item.quantity || 0) * (item.unit_price || 0), 0),
  );

  mismatch = computed(() => {
    const amount = this.amount();
    return amount > 0 && Math.abs(this.total() - amount) > 0.009;
  });

  addRow(): void {
    this.items.update((rows) => [...rows, { description: '', quantity: 1, unit_price: 0 }]);
    this.change();
  }

  removeRow(index: number): void {
    this.items.update((rows) => rows.filter((_, i) => i !== index));
    this.change();
  }

  preset(rows: LineItem[] | null): void {
    if (rows && rows.length) {
      this.items.set(rows.map((r) => ({ ...r })));
    }
  }

  change(): void {
    this.itemsChange.emit(this.items());
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import { TextareaModule } from 'primeng/textarea';
import type { HttpErrorResponse } from '@angular/common/http';
import type { ApiErrorBody } from '@shared/models/api.models';

/**
 * The shared reason/notes dialog (T3-02): every reject / cancel / resolve
 * action that the API requires a reason for goes through here — no action
 * ever sends hard-coded human text. The page receives the typed text via
 * `submit` and posts it under the field name its endpoint expects.
 */
@Component({
  selector: 'app-reason-dialog',
  standalone: true,
  imports: [TranslatePipe, DialogModule, ButtonModule, FormsModule, TextareaModule],
  template: `
    <p-dialog appendTo="body"
      [visible]="visible()"
      (visibleChange)="visible.set($event)"
      [header]="header() | translate"
      [modal]="true"
      [draggable]="false"
      [resizable]="false"
      styleClass="dialog"
      [breakpoints]="{ '576px': '100vw' }"
      [style]="{ width: 'min(480px, 94vw)' }"
      [closable]="!sending()"
    >
      <div class="field">
        <label class="field__label" for="reason-dialog-input">{{ label() | translate }} *</label>
        <textarea
          id="reason-dialog-input"
          pTextarea
          rows="3"
          [(ngModel)]="reason"
          name="reason"
          [maxlength]="maxLength()"
          style="width: 100%"
          (keydown.control.enter)="confirm()"
        ></textarea>
        @if (invalid()) {
          <p class="field__error">{{ 'validation.reason_min' | translate: { min: minLength() } }}</p>
        }
      </div>
      @if (alert()) {
        <div class="dialog__alert" role="alert">
          <svg width="16" height="16" aria-hidden="true">
            <use href="assets/icons/sprite.svg#tabler-alert-triangle" />
          </svg>
          <span>{{ alert() }}</span>
        </div>
      }
      <p-footer>
        <div class="u-flex u-gap-2" style="justify-content: flex-end">
          <p-button [label]="'common.cancel' | translate" severity="secondary" [text]="true" [disabled]="sending()" (onClick)="visible.set(false)" />
          <p-button [label]="submitLabel() | translate" [loading]="sending()" [disabled]="sending()" (onClick)="confirm()" />
        </div>
      </p-footer>
    </p-dialog>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ReasonDialogComponent {
  header = input.required<string>();
  label = input('common.reason');
  submitLabel = input('common.confirm');
  /** set while the caller's request is in flight */
  sending = input(false);
  /** a failed request — its message is shown inside the dialog */
  error = input<HttpErrorResponse | null>(null);
  minLength = input(3);
  maxLength = input(1000);

  submit = output<string>();

  visible = signal(false);
  reason = signal('');
  private tried = signal(false);

  invalid = computed(() => this.tried() && this.reason().trim().length < this.minLength());

  alert = computed(() => {
    const err = this.error();
    if (!err) {
      return null;
    }
    const body = err.error as ApiErrorBody | null;
    return body?.message ?? null;
  });

  open(): void {
    this.reason.set('');
    this.tried.set(false);
    this.visible.set(true);
  }

  done(): void {
    this.visible.set(false);
  }

  confirm(): void {
    this.tried.set(true);
    const value = this.reason().trim();
    if (value.length < this.minLength()) {
      return;
    }
    this.submit.emit(value);
  }
}

import type {
  AfterViewInit,
  ElementRef} from '@angular/core';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { MotionService } from '@core/motion/motion.service';

/**
 * Stat tile (plan 11.2): label, hero figure in the display face, companion
 * line. The figure counts up once per session view when motion allows (12.2).
 */
@Component({
  selector: 'app-stat-tile',
  standalone: true,
  imports: [TranslatePipe, MoneyPipe],
  template: `
    <div class="stat-tile" [class.stat-tile--wide]="wide()" [class.stat-tile--inset]="inset()">
      <span class="stat-tile__label">
        @if (icon()) {
          <ng-content select="[icon]" />
        }
        {{ label() | translate }}
      </span>
      @if (money()) {
        <span class="stat-tile__value" [class.stat-tile__value--hero]="hero()" #value
          >{{ displayValue() | money: false }}<span class="stat-tile__currency"> ج.م</span></span
        >
      } @else {
        <span class="stat-tile__value" [class.stat-tile__value--hero]="hero()">{{ displayValue() }}</span>
      }
      @if (caption()) {
        <span class="stat-tile__caption">{{ caption() | translate }}</span>
      }
      @if (hint()) {
        <span class="stat-tile__caption u-bidi">{{ hint() }}</span>
      }
    </div>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class StatTileComponent implements AfterViewInit {
  label = input.required<string>();
  value = input<string | number>(0);
  money = input(false);
  hero = input(false);
  wide = input(false);
  inset = input(false);
  caption = input('');
  hint = input('');
  icon = input(false);

  private motion = inject(MotionService);
  private valueEl = viewChild<ElementRef<HTMLElement>>('value');
  private counted = signal(false);

  displayValue = computed(() => this.value());

  ngAfterViewInit(): void {
    if (!this.money() || this.counted()) {
      return;
    }
    const level = this.motion.level();
    const el = this.valueEl()?.nativeElement;
    if (!el) {
      return;
    }
    if (level === 'off' || level === 'lite' || !this.parse(this.value())) {
      return;
    }
    this.counted.set(true);
    this.countUp(el, this.parse(this.value())!);
  }

  private parse(v: string | number): number | null {
    const n = typeof v === 'string' ? parseFloat(v) : v;
    return isFinite(n) ? n : null;
  }

  /** 600ms one-shot count-up, GSAP-free (transform/opacity-only budget kept for elsewhere). */
  private countUp(el: HTMLElement, target: number): void {
    const start = performance.now();
    const dur = 600;
    const step = (now: number) => {
      const t = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = (target * eased).toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
      if (t < 1) {
        requestAnimationFrame(step);
      }
    };
    requestAnimationFrame(step);
  }
}
